                "<meta[^>]*content=[\"']([^\"']*)[\"'][^>]*name=[\"']description[\"']",
                Pattern.CASE_INSENSITIVE
        );
        matcher = pattern.matcher(html);
        if (matcher.find()) {
            return matcher.group(1).trim();
        }

        return null;
    }
